      "template": "/* Q1: joins=0, agg=True, sub=False, tables=1, rows=14, time=56.0ms */\nSELECT\n  stmt,\n  rfile,\n  COUNT(*) AS cnt,\n  COUNT(DISTINCT adsh) AS num_filings,\n  AVG(line) AS avg_line_num\nFROM pre\nWHERE\n  NOT stmt IS NULL\nGROUP BY\n  stmt,\n  rfile\nORDER BY\n  cnt DESC NULLS LAST\n",
