      "template": "/* Q3: joins=2, agg=True, sub=True, tables=2, rows=100, time=228.0ms */\nSELECT\n  s.name,\n  s.cik,\n  SUM(n.value) AS total_value\nFROM num AS n\nJOIN sub AS s\n  ON n.adsh = s.adsh\nWHERE\n  n.uom = :uom_eq AND s.fy = :fy_eq AND NOT n.value IS NULL\nGROUP BY\n  s.name,\n  s.cik\nHAVING\n  SUM(n.value) > (\n    SELECT\n      AVG(sub_total)\n    FROM (\n      SELECT\n        SUM(n2.value) AS sub_total\n      FROM num AS n2\n      JOIN sub AS s2\n        ON n2.adsh = s2.adsh\n      WHERE\n        n2.uom = :uom_eq_2 AND s2.fy = :fy_eq_2 AND NOT n2.value IS NULL\n      GROUP BY\n        s2.cik\n    ) AS avg_sub\n  )\nORDER BY\n  total_value DESC NULLS LAST\nLIMIT :limit\n",
